require __DIR__.'/inc/core.php';require __DIR__.'/inc/quote-richtext.php';auth();if(!ekAdmin()){http_response_code(403);exit('Yönetici yetkisi gerekir.');}require __DIR__.'/inc/layout.php';$pdo=db();$id=max(0,(int)($_GET['id']??$_POST['id']??0));$copy=max(0,(int)($_GET['copy']??0));$fields=['service_scope','payment_terms','delivery_time','additional_terms'];$error='';
