$row=[];$read=$id?:$copy;if($read){$s=$pdo->prepare('SELECT * FROM moving_content_templates WHERE id=?');$s->execute([$read]);$row=$s->fetch()?:[];if(!$row){http_response_code(404);exit('Şablon bulunamadı');}}if(!empty($row['transport_process']))$row['service_scope']=ekRichDisplay($row['service_scope']??'').'<div>'.ekRichDisplay($row['transport_process']).'</div>';if($copy){$id=0;$row['name']=($row['name']??'').' - Kopya';}
top('Teklif İçeriği Düzenle'); ?>
